import CryptoKit
import Foundation
import Testing
@testable import TeleportCore

/// Cross-platform conformance: protocol/vectors.json is generated by the TS reference.
struct Vectors: Decodable {
    struct KP: Decodable { let d: String; let pub: String }
    struct Case: Decodable {
        let name: String
        let plaintext: String
        let eph: KP
        let derived_key: String
        let env: Envelope
    }
    struct Invalid: Decodable { let name: String; let error: String; let env: Envelope }
    struct Blob: Decodable { let key: String; let n: String; let plaintext: String; let ciphertext: String }
    struct Card: Decodable { let encoded: String }
    struct PairSide: Decodable { let eph: KP; let plaintext: String; let env: Envelope }
    struct PairInvalid: Decodable { let name: String; let error: String; let ps: String; let env: Envelope }
    struct Pairing: Decodable {
        let ps: String
        let a_ks: KP
        let b_ka: KP
        let qr: String
        let b_card: String
        let proof: String
        let pair: PairSide
        let pair_ok: PairSide
        let invalid: [PairInvalid]
    }

    let now: Int
    let recipient_ka: KP
    let sender_ks: KP
    let cases: [Case]
    let invalid: [Invalid]
    let blob: Blob
    let pairing_card: Card
    let pairing: Pairing

    static let shared: Vectors = {
        let url = URL(filePath: #filePath)
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .deletingLastPathComponent().deletingLastPathComponent().deletingLastPathComponent()
            .appending(path: "protocol/vectors.json")
        return try! JSONDecoder().decode(Vectors.self, from: Data(contentsOf: url))
    }()
}

private func b(_ s: String) -> Data { Data(base64URL: s)! }

private let V = Vectors.shared
private let recipient = SoftwareAgreementKey(try! .init(rawRepresentation: b(V.recipient_ka.d)))
private let sender = SoftwareSigningKey(try! .init(rawRepresentation: b(V.sender_ks.d)))

@Test func publicKeysMatchVectors() {
    #expect(recipient.publicKey == b(V.recipient_ka.pub))
    #expect(sender.publicKey == b(V.sender_ks.pub))
}

@Test(arguments: V.cases.map(\.name))
func opensVector(name: String) throws {
    let c = V.cases.first { $0.name == name }!
    let pt = try TeleportCrypto.open(c.env, ownKa: recipient, senderKs: sender.publicKey, now: V.now)
    #expect(pt == b(c.plaintext))
}

@Test(arguments: V.cases.map(\.name))
func sealMatchesVector(name: String) throws {
    let c = V.cases.first { $0.name == name }!
    let env = try TeleportCrypto.seal(
        kind: c.env.k, plaintext: b(c.plaintext), signer: sender, recipientKa: recipient.publicKey,
        id: b(c.env.id), ts: c.env.ts,
        ephemeral: try .init(rawRepresentation: b(c.eph.d)), nonce: b(c.env.n))
    var expected = c.env
    expected.sig = env.sig  // ECDSA is randomized
    #expect(env == expected)
    // …and our own signature must verify with the reference's rules.
    _ = try TeleportCrypto.open(env, ownKa: recipient, senderKs: sender.publicKey, now: V.now)
}

@Test(arguments: V.invalid.map(\.name))
func rejectsInvalid(name: String) {
    let c = V.invalid.first { $0.name == name }!
    #expect(throws: OpenError(rawValue: c.error)!) {
        try TeleportCrypto.open(c.env, ownKa: recipient, senderKs: sender.publicKey, now: V.now)
    }
}

@Test func rejectsStale() {
    #expect(throws: OpenError.stale) {
        try TeleportCrypto.open(V.cases[0].env, ownKa: recipient, senderKs: sender.publicKey, now: V.now + 2 * 86_400)
    }
}

@Test func blobDecrypts() throws {
    let pt = try TeleportCrypto.openBlob(b(V.blob.ciphertext), key: b(V.blob.key), nonce: b(V.blob.n))
    #expect(pt == b(V.blob.plaintext))
}

@Test func blobRoundTrip() throws {
    let data = Data.random(5000)
    let s = try TeleportCrypto.sealBlob(data)
    #expect(try TeleportCrypto.openBlob(s.ciphertext, key: s.key, nonce: s.nonce) == data)
}

@Test func v1PairingCardIsRejected() {
    #expect(throws: (any Error).self) { try PairingCard.decode(V.pairing_card.encoded) }
}

// MARK: Pairing v2

private let P = V.pairing

@Test func qrCardV2Decodes() throws {
    let card = try PairingCard.decode(P.qr)
    #expect(card.v == 2)
    #expect(card.ps == P.ps)
    #expect(Data(base64URL: card.ka) == b(V.recipient_ka.pub))
    #expect(try PairingCard.decode(try card.encoded()) == card)
}

@Test func pairProofMatches() {
    #expect(TeleportCrypto.pairProof(secret: b(P.ps), cardJSON: P.b_card) == b(P.proof))
}

@Test func pairPlaintextMatches() throws {
    #expect(try TeleportCrypto.pairPlaintext(cardJSON: P.b_card, proof: b(P.proof)) == b(P.pair.plaintext))
}

@Test func openPairVector() throws {
    let (card, json) = try TeleportCrypto.openPair(P.pair.env, ownKa: recipient, secret: b(P.ps), now: V.now)
    #expect(json == P.b_card)
    #expect(card.name == "Pixel 8")
    #expect(card.platform == .android)
}

@Test func sealPairMatchesVector() throws {
    let env = try TeleportCrypto.seal(
        kind: .pair, plaintext: b(P.pair.plaintext), signer: sender, recipientKa: recipient.publicKey,
        id: b(P.pair.env.id), ts: P.pair.env.ts,
        ephemeral: try .init(rawRepresentation: b(P.pair.eph.d)), nonce: b(P.pair.env.n))
    var expected = P.pair.env
    expected.sig = env.sig
    #expect(env == expected)
}

@Test func pairOKOpensWithQRKey() throws {
    let bKa = SoftwareAgreementKey(try .init(rawRepresentation: b(P.b_ka.d)))
    let pt = try TeleportCrypto.open(P.pair_ok.env, ownKa: bKa, senderKs: b(P.a_ks.pub), now: V.now)
    #expect(pt == b(P.pair_ok.plaintext))
}

@Test(arguments: P.invalid.map(\.name))
func rejectsInvalidPair(name: String) {
    let c = P.invalid.first { $0.name == name }!
    #expect(throws: OpenError(rawValue: c.error)!) {
        try TeleportCrypto.openPair(c.env, ownKa: recipient, secret: b(c.ps), now: V.now)
    }
}

@Test func envelopeJSONRoundTrip() throws {
    let env = V.cases[0].env
    #expect(try Envelope.parse(try env.jsonString()) == env)
}
